// noCrossHostRedirect follows at most 10 redirects and never sends
// credentials to another host.
func noCrossHostRedirect(req *http.Request, via []*http.Request) error {
	if len(via) >= 10 {
		return errors.New("stopped after 10 redirects")
	}
	if len(via) > 0 && req.URL.Host != via[0].URL.Host {
		for k := range req.Header {
			if IsSensitiveHeader(k) {
				req.Header.Del(k)
			}
		}
	}
	return nil
}

func buildTLS(c TLSConfig) (*tls.Config, error) {
	cfg := &tls.Config{MinVersion: tls.VersionTLS12, InsecureSkipVerify: c.InsecureSkipVerify}
	pem := []byte(c.CACertPEM)
	if c.CACertPath != "" {
		data, err := os.ReadFile(c.CACertPath)
		if err != nil {
			return nil, ConfigError("tls CA certificate file cannot be read")
		}
		pem = data
	}
	if len(pem) > 0 {
		pool := x509.NewCertPool()
		if !pool.AppendCertsFromPEM(pem) {
			return nil, ConfigError("tls CA certificate is not valid PEM")
		}
		cfg.RootCAs = pool
	}
	if c.ClientCertPath != "" {
		cert, err := tls.LoadX509KeyPair(c.ClientCertPath, c.ClientKeyPath)
		if err != nil {
			return nil, ConfigError("tls client certificate or key cannot be loaded")
		}
		cfg.Certificates = []tls.Certificate{cert}
	}
	return cfg, nil
}

