// attempt sends one HTTP request. sent reports whether the request may have
// reached the server (false only for failures before the headers were written).
func (t *httpTransport) attempt(ctx, totalCtx context.Context, req *request, u *url.URL, safeURL string,
	body []byte, contentType string, attempt int, op string,
) (*response, bool, *Error) {
	actx, cancel := context.WithTimeout(totalCtx, t.cfg.RequestTimeout)
	defer cancel()

	var wrote atomic.Bool
	trace := &httptrace.ClientTrace{WroteHeaders: func() { wrote.Store(true) }}
	actx = httptrace.WithClientTrace(actx, trace)

	var reader io.Reader
	if body != nil {
		reader = bytes.NewReader(body)
	}
	hreq, err := http.NewRequestWithContext(actx, req.Method, u.String(), reader)
	if err != nil {
		return nil, false, ValidationError(op, "request cannot be built")
	}
	hreq.Header.Set("User-Agent", t.userAgent)
	hreq.Header.Set("Accept", "application/json")
	for k, v := range t.cfg.Headers {
		hreq.Header.Set(k, v)
	}
	for k, vs := range req.Header {
		hreq.Header[http.CanonicalHeaderKey(k)] = append([]string(nil), vs...)
	}
	if contentType != "" {
		hreq.Header.Set("Content-Type", contentType)
	}

	t.hooks.request(RequestInfo{Method: req.Method, URL: safeURL, Headers: RedactHeaders(hreq.Header), Attempt: attempt})
	t.log(slog.LevelDebug, "http request",
		slog.String("method", req.Method), slog.String("url", safeURL), slog.Int("attempt", attempt))

	start := t.now()
	resp, err := t.client.Do(hreq)
	if err != nil {
		return nil, wrote.Load(), t.networkError(ctx, totalCtx, actx, op, err)
	}
	data, err := io.ReadAll(resp.Body)
	_ = resp.Body.Close()
	if err != nil {
		return nil, true, t.networkError(ctx, totalCtx, actx, op, err)
	}
	res := &response{Status: resp.StatusCode, Header: resp.Header, Body: data, RequestID: requestID(resp.Header)}
	elapsed := t.now().Sub(start)
	t.hooks.response(ResponseInfo{Method: req.Method, URL: safeURL, Status: res.Status, Duration: elapsed, Attempt: attempt, RequestID: res.RequestID})
	t.log(slog.LevelDebug, "http response",
		slog.String("method", req.Method), slog.String("url", safeURL), slog.Int("status", res.Status),
		slog.Duration("duration", elapsed), slog.Int("attempt", attempt))
	return res, true, nil
}

// contextFailure maps a context error: caller cancel/deadline first, then the total timeout.
func (t *httpTransport) contextFailure(ctx, totalCtx context.Context, op string, err error) *Error {
	switch {
	case ctx.Err() != nil:
		return contextErr(op, ctx.Err())
	case totalCtx.Err() != nil:
		return &Error{Code: ErrorCodeTimeout, Message: fmt.Sprintf("%s: total timeout of %s exceeded", op, t.cfg.TotalTimeout), Retryable: true, Err: totalCtx.Err()}
	}
	return contextErr(op, err)
}

// networkError classifies a failed attempt.
func (t *httpTransport) networkError(ctx, totalCtx, actx context.Context, op string, err error) *Error {
	if ctx.Err() != nil || totalCtx.Err() != nil {
		return t.contextFailure(ctx, totalCtx, op, err)
	}
	cause := t.redactCause(err)
	if actx.Err() != nil {
		return &Error{Code: ErrorCodeTimeout, Message: fmt.Sprintf("%s: request timeout of %s exceeded", op, t.cfg.RequestTimeout), Retryable: true, Err: cause}
	}
	var nerr net.Error
	if errors.As(err, &nerr) && nerr.Timeout() {
		return &Error{Code: ErrorCodeTimeout, Message: op + ": connect timeout exceeded", Retryable: true, Err: cause}
	}
	return &Error{Code: ErrorCodeUnavailable, Message: op + ": network error: " + t.redact(innerMessage(err)), Retryable: true, Err: cause}
}

// redactCause replaces the URL inside *url.Error (it may carry query secrets)
// while keeping the error chain intact for errors.Is.
func (t *httpTransport) redactCause(err error) error {
	var uerr *url.Error
	if errors.As(err, &uerr) {
		return &url.Error{Op: uerr.Op, URL: t.redact(RedactURL(uerr.URL)), Err: uerr.Err}
	}
	return err
}

func innerMessage(err error) string {
	var uerr *url.Error
	if errors.As(err, &uerr) {
		return uerr.Err.Error()
	}
	return err.Error()
}

func encodeBody(req *request) ([]byte, string, error) {
	if req.JSON != nil {
		b, err := json.Marshal(req.JSON)
		if err != nil {
			return nil, "", err
		}
		return b, "application/json", nil
	}
	if req.Body != nil {
		ct := req.ContentType
		if ct == "" {
			ct = "application/octet-stream"
		}
		return req.Body, ct, nil
	}
	return nil, "", nil
}

func requestID(h http.Header) string {
	for _, name := range requestIDHeaders {
		if v := h.Get(name); v != "" {
			return v
		}
	}
	return ""
}

// vendorErrorText extracts a short error text from a response body.
func vendorErrorText(res *response) string {
	body := bytes.TrimSpace(res.Body)
	if len(body) == 0 {
		return ""
	}
	var doc any
	if json.Unmarshal(body, &doc) == nil {
		return jsonErrorText(doc)
	}
	ct := res.Header.Get("Content-Type")
	if strings.HasPrefix(ct, "text/plain") {
		line, _, _ := strings.Cut(string(body), "\n")
		return line
	}
	return ""
}

func jsonErrorText(doc any) string {
	switch v := doc.(type) {
	case string:
		return v
	case []any:
		parts := make([]string, 0, len(v))
		for _, item := range v {
			if s := jsonErrorText(item); s != "" {
				parts = append(parts, s)
			}
		}
		return strings.Join(parts, "; ")
	case map[string]any:
		for _, key := range []string{"errors", "error", "message", "msg", "detail", "error_description", "title"} {
			if inner, ok := v[key]; ok {
				if s := jsonErrorText(inner); s != "" {
					return s
				}
			}
		}
	}
	return ""
}

func remaining(ctx context.Context, now time.Time) time.Duration {
	deadline, ok := ctx.Deadline()
	if !ok {
		return time.Duration(1<<63 - 1)
	}
	return deadline.Sub(now)
}

// sleepContext waits for d or until ctx is done.
func sleepContext(ctx context.Context, d time.Duration) error {
	if d <= 0 {
		return ctx.Err()
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}
